#include <vector>
#include <unordered_map>

using namespace std;

class Solution {
public:
    int longestWPI(vector<int>& hours) {
        unordered_map<int, int> seen;
        int sum = 0, res = 0;
        for (int i = 0; i < hours.size(); ++i) {
            sum += hours[i] > 8 ? 1 : -1;
            if (sum > 0)
                res = i + 1;
            else {
                if (seen.count(sum - 1))
                    res = max(res, i - seen[sum - 1]);
            }
            if (!seen.count(sum)) seen[sum] = i;
        }
        return res;
    }
};
